"""Public storefront only. Never packages complete paid editions."""
from pathlib import Path
import importlib.util,json
from html import escape as e
ROOT=Path(__file__).resolve().parents[1]
spec=importlib.util.spec_from_file_location('base',ROOT/'scripts/build_site.py');base=importlib.util.module_from_spec(spec);spec.loader.exec_module(base)
COPY=json.loads((ROOT/'assets/products/translations.json').read_text());c=COPY['en']
def t(k,tag='span',cls=''):return f'<{tag} class="{cls}" data-i18n="{k}">{e(c[k])}</{tag}>'
def btn(k,url,kind='primary'):return f'<a class="btn {kind}" href="{url}" data-language-route>{t(k)}<span aria-hidden="true">↗</span></a>'
def artwork(kind='workflow'):
 if kind in ('studio','lighting'):
  return '<svg viewBox="0 0 460 240" aria-hidden="true"><rect x="30" y="30" width="95" height="30" rx="8" fill="#38bdf8"/><path d="M120 60L230 130L160 150Z" fill="#38bdf8" opacity=".25"/><circle cx="235" cy="120" r="24" fill="#8b5cf6"/><rect x="217" y="170" width="36" height="55" rx="8" fill="#111d35"/><path d="M235 170V145" stroke="#2563eb" stroke-width="4"/><rect x="350" y="75" width="18" height="85" rx="7" fill="white" stroke="#2563eb" stroke-width="3"/><path d="M150 20H400" stroke="#a3b7d4" stroke-width="3" stroke-dasharray="6 6"/></svg>'
 if kind=='product':
  return '<svg viewBox="0 0 460 240" aria-hidden="true"><rect x="15" y="25" width="200" height="185" rx="20" fill="#cbd5e1"/><rect x="245" y="25" width="200" height="185" rx="20" fill="#dbeafe"/><ellipse cx="110" cy="182" rx="60" ry="15" fill="#94a3b8"/><ellipse cx="340" cy="182" rx="45" ry="10" fill="#abcdf5"/><g fill="#38bdf8"><rect x="75" y="85" width="70" height="95" rx="15"/><rect x="305" y="85" width="70" height="95" rx="15"/></g><g fill="#111d35"><rect x="90" y="65" width="40" height="25" rx="5"/><rect x="320" y="65" width="40" height="25" rx="5"/></g></svg>'
 return '<svg viewBox="0 0 460 240" aria-hidden="true"><path d="M75 120H385" stroke="#38bdf8" stroke-width="4"/>'+''.join(f'<rect x="{25+i*110}" y="70" width="85" height="100" rx="20" fill="{color}"/><circle cx="{67+i*110}" cy="120" r="16" fill="white" opacity=".7"/>' for i,color in enumerate(['#2563eb','#38bdf8','#8b5cf6','#111d35']))+'</svg>'
def header(path,title,desc):
 h=base.head(False).replace('<script src="/assets/site.js?v=products-1" defer></script>','<script src="/assets/site.js?v=products-1" defer></script><script src="/assets/products/store.js?v=1" defer></script><link rel="stylesheet" href="/assets/products/store.css?v=1">')
 h=h.replace('data-page="home"','data-page="product"').replace('https://alialkhuzaee.com/?lang=','https://alialkhuzaee.com'+path+'?lang=')
 # Accurate page-specific metadata; shared runtime localizes it.
 import re
 h=re.sub(r'<title>.*?</title>','<title>'+e(title)+'</title>',h)
 h=re.sub(r'<link rel="canonical"[^>]+>',f'<link rel="canonical" href="https://alialkhuzaee.com{path}">',h)
 h=h.replace('<head>','<head><meta name="robots" content="noindex,nofollow">')
 h=re.sub(r'<meta property="og:title"[^>]+>', '<meta property="og:title" content="'+e(title)+'">',h)
 h=re.sub(r'<meta property="og:description"[^>]+>', '<meta property="og:description" content="'+e(desc)+'">',h)
 h=re.sub(r'<meta property="og:url"[^>]+>', '<meta property="og:url" content="https://alialkhuzaee.com'+path+'">',h)
 h=re.sub(r'<meta property="og:image"[^>]+>', '<meta property="og:image" content="https://alialkhuzaee.com/assets/products/preview-en-1.webp">',h)
 h=h.replace('hreflang="x-default" href="https://alialkhuzaee.com/"','hreflang="x-default" href="https://alialkhuzaee.com'+path+'"')
 h=h.replace('<meta name="description" content="'+e(base.HOME['seoHome'])+'">','<meta name="description" content="'+e(desc)+'">')
 h=h.replace('<body id="top" data-page="product">',f'<body id="top" data-page="product" data-product-route="{path}">')
 return h+base.nav(False)
def previews():return '<section class="section paper" id="pages"><div class="shell">'+t('previewTitle','h2')+t('previewNote','p','section-intro')+'<div class="book-previews">'+''.join(f'<a href="/assets/products/preview-en-{p}.webp" data-preview-link="{p}" target="_blank" rel="noopener"><img src="/assets/products/preview-en-{p}.webp" data-preview="{p}" width="540" height="767" loading="lazy" alt="{e(c["previewAlt"])}"></a>' for p in [1,6,16,62])+'</div></div></section>'
def purchase():return '<section class="section navy" id="purchase"><div class="shell purchase-grid"><div>'+t('buyCta','h2')+t('editionNotice','p')+t('oneTime','p','fineprint')+'</div><div class="purchase-box">'+t('launchPrice','p','eyebrow')+'<p class="product-price" dir="ltr">€2.99</p><label for="edition">'+t('editionLabel')+'</label><select id="edition"><option value="ar">العربية</option><option value="en" selected>English</option><option value="ru">Русский</option></select><button class="btn white" type="button" data-checkout disabled>'+t('checkoutLive')+'</button>'+t('checkoutPending','p','checkout-status')+btn('legalLabel','/products/creator-guide/terms/','text')+'</div></div></section>'
def build():
 catalog=header('/products/',c['navProducts']+' | Ali Alkhuzaee',c['catalogIntro'])+'<main id="main"><section class="section product-hero"><div class="shell">'+t('navProducts','p','eyebrow')+t('catalogTitle','h1')+t('catalogIntro','p','hero-intro')+'<article class="catalog-card"><a href="/products/creator-guide/?lang=en" data-language-route><img src="/assets/products/preview-en-1.webp" data-preview="1" width="540" height="767" alt="'+e(c['previewAlt'])+'"></a><div>'+t('productTitle','h2')+t('productIntro','p')+'<p class="price-small">€2.99 <small>'+t('launchPrice')+'</small></p>'+btn('viewProduct','/products/creator-guide/')+'</div></article></div></section></main>'+base.footer()+'</body></html>'
 product=header('/products/creator-guide/',c['productTitle']+' | Ali Alkhuzaee',c['productIntro'])+'<main id="main"><section class="product-hero section"><div class="shell product-hero-grid"><div>'+t('productEyebrow','p','eyebrow')+t('productTitle','h1')+t('productIntro','p','hero-intro')+'<div class="hero-buttons">'+btn('presentationCta','#presentation')+btn('buyCta','#purchase','outline')+'</div>'+t('oneTime','p','fineprint')+'</div><div class="book-stage"><img src="/assets/products/preview-en-1.webp" data-preview="1" width="540" height="767" alt="'+e(c['previewAlt'])+'" fetchpriority="high"></div></div></section><section class="section navy"><div class="shell">'+t('inside','h2')+t('insideIntro','p','section-intro')+'<ol class="chapter-grid">'+''.join(f'<li data-array="chapters.{i}">{e(x)}</li>' for i,x in enumerate(c['chapters']))+'</ol></div></section><section class="section paper" id="presentation"><div class="shell">'+t('presentationLabel','p','eyebrow')+t('presentationTitle','h2')+t('presentationIntro','p','section-intro')+'<div class="presentation" aria-roledescription="carousel"><div class="slide-toolbar"><button type="button" data-prev aria-label="Previous section" data-label="previousSlide">←</button><output id="slide-progress" aria-live="polite">1 / 16</output><button type="button" data-next aria-label="Next section" data-label="nextSlide">→</button></div><div class="slide-track">'+''.join(f'<article class="presentation-slide" data-slide="{i}"><div><span class="slide-number">{i+1:02d}</span><h3 data-array="slides.{i}.title">{e(s["title"])}</h3><p data-array="slides.{i}.text">{e(s["text"])}</p></div><div class="slide-art">'+artwork(s['art'])+'</div></article>' for i,s in enumerate(c['slides']))+'</div><div class="slide-dots">'+''.join(f'<button type="button" data-goto="{i}" aria-label="{i+1}">{i+1}</button>' for i in range(16))+'</div></div></div></section>'+previews()+purchase()+'</main>'+base.footer()+'</body></html>'
 terms=header('/products/creator-guide/terms/',c['legalLabel']+' | Ali Alkhuzaee',c['legalIntro'])+'<main id="main"><section class="section paper"><div class="shell legal-copy">'+t('legalLabel','h1')+t('legalIntro','p','hero-intro')+''.join(t(k,'p') for k in ['taxTerms','deliveryTerms','refundTerms','privacyTerms'])+btn('backProduct','/products/creator-guide/','outline')+'<p><a href="mailto:ali@alialkhuzaee.com">ali@alialkhuzaee.com</a></p></div></section></main>'+base.footer()+'</body></html>'
 for path,html in [('products/index.html',catalog),('products/creator-guide/index.html',product),('products/creator-guide/terms/index.html',terms)]:
  p=ROOT/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(html+'\n')
if __name__=='__main__':build()
